public sealed class OperatingReportTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public async Task InitializeAsync(){await db.InitializeAsync();await S("UPDATE platform.document_jobs SET state='FAILED',last_error='isolated_test_cleanup',lease_token=NULL,lease_until=NULL WHERE state IN('QUEUED','PROCESSING','RETRY')");}public async Task DisposeAsync(){await S("UPDATE platform.document_jobs SET state='FAILED',last_error='isolated_test_cleanup',lease_token=NULL,lease_until=NULL WHERE company_id=@c AND state IN('QUEUED','PROCESSING','RETRY')",("c",db.Company));await db.DisposeAsync();}
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static JsonElement Snap(JsonElement x)=>x.GetProperty("snapshot");
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 private async Task<OperatingReportInput> Input(string kind)=>new(kind,await Today(),(await Today()).AddDays(1));
 private static Task<HttpResponseMessage> Capture(HttpClient c,OperatingReportInput x,string? key=null)=>Send(c,HttpMethod.Post,"/operating-report-runs",x,key:key);
 private static Task<HttpResponseMessage> Export(HttpClient c,Guid id,string? key=null,long version=1)=>Send(c,HttpMethod.Post,$"/operating-report-runs/{id}/export",version:version,key:key);
 private async Task<JsonElement> Live(HttpClient c,string kind,string suffix="")
 {var x=await Input(kind);return await Get(c,$"/accounting/reports/operating?kind={kind}&from={x.From:yyyy-MM-dd}&to={x.To:yyyy-MM-dd}"+suffix);}
 private async Task<JsonElement> Statement(HttpClient c,Guid customer,string? key=null,DateOnly? from=null,DateOnly? to=null)=>await Expect(await Send(c,HttpMethod.Post,$"/customers/{customer}/statements",new StatementPeriodInput(from??await Today(),to??(await Today()).AddDays(1)),key:key),HttpStatusCode.Created);
 private async Task<(SalesData Data,Guid Invoice,Guid Line,Guid OrderLine)> Invoice(HttpClient c,string basis="NON_CASH")
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Report service",p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);var q=await Submitted(c,d.Draft(1)with{Lines=[new(d.BoxUnit,Quantity:1,UnitPrice:100)]});var o=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var ol=(await Get(c,$"/sales-orders/{o}")).GetProperty("lines")[0].GetProperty("id").GetGuid();var v=(await Get(c,$"/sales-orders/{o}/invoiceable")).GetProperty("version").GetInt64();var i=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{o}/invoices",new InvoiceInput([new(ol,1)],"Completed"),v),HttpStatusCode.Created);return(d,Id(i),i.GetProperty("lines")[0].GetProperty("id").GetGuid(),ol);}
 private async Task<(Guid Supplier,Guid Bill,Guid Line)> Bill(HttpClient c,string basis="NON_CASH")
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Report supplier",null));var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@c,@code,'Operating expense','EXPENSE')RETURNING id",("c",db.Company),("code",Code())))!;var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code='GST'",("c",db.Company)))!;var day=await Today();var b=await Expect(await Send(c,HttpMethod.Post,"/supplier-expense-bills",new ExpenseBillInput(supplier,Code(),day,day.AddDays(30),day,[new(account,"Expense",100,10,tax)],Code(),day)),HttpStatusCode.Created);return(supplier,Id(b.GetProperty("bill")),Id(b.GetProperty("lines")[0]));}
 private sealed class Mailer(DocumentWorkException? error=null):IDocumentMailer{public int Calls;public Task<string> SendAsync(Guid id,JsonElement p,CancellationToken ct){Interlocked.Increment(ref Calls);if(error is not null)throw error;return Task.FromResult("accepted-"+id);}}
 private sealed class Scanner:IFileScanner{public Task<bool>IsCleanAsync(byte[]bytes,CancellationToken ct)=>Task.FromResult(true);}
 private sealed class Exporter(DocumentWorkException? error=null):IReportExporter{public int Calls;public Task<byte[]>RenderAsync(JsonElement x,CancellationToken ct){Interlocked.Increment(ref Calls);if(error is not null)throw error;return new CsvReportExporter().RenderAsync(x,ct);}}
 private async Task RunJob(Guid job,IReportExporter? exporter=null,IPdfRenderer? renderer=null,IDocumentMailer? mailer=null)
 {await S("UPDATE platform.document_jobs SET available_at=now()-interval '1 day'WHERE company_id=@c AND id=@j",("c",db.Company),("j",job));await using var source=NpgsqlDataSource.Create(db.Worker);Assert.True(await new DocumentWorker(source,renderer??new ReportLabPdfRenderer(new(){PythonExecutable=Environment.GetEnvironmentVariable("HTT_TEST_PDF_PYTHON")??"python3"}),new Scanner(),mailer??new Mailer(),exporter).ProcessOneAsync());}
 private static Task<JsonElement> Job(HttpClient c,Guid job)=>Get(c,$"/document-jobs/{job}");
 private async Task<(Guid Job,Guid File)> Generated(HttpClient c,Guid doc,bool export)
 {var j=Id(await Expect(await(export?Export(c,doc):Send(c,HttpMethod.Post,$"/documents/{doc}/pdf",version:1)),HttpStatusCode.Accepted));await RunJob(j);var view=await Job(c,j);Assert.True(view.GetProperty("state").GetString()=="SUCCEEDED",view.GetRawText());return(j,view.GetProperty("outputFileId").GetGuid());}
 [Theory][InlineData("PURCHASING")][InlineData("ARAP")][InlineData("INVENTORY")][InlineData("BANKING")]
 public async Task Empty_report_snapshots_export_verified_CSV_without_financial_side_effects(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var n=await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company));var r=await Expect(await Capture(c,await Input(kind)),HttpStatusCode.Created);var(j,file)=await Generated(c,Id(r),true);using var download=await c.GetAsync($"/api/v1/files/{file}/content");Assert.Equal(HttpStatusCode.OK,download.StatusCode);Assert.Equal("text/csv",download.Content.Headers.ContentType!.MediaType);var bytes=await download.Content.ReadAsByteArrayAsync();Assert.True(bytes.AsSpan().StartsWith(Encoding.UTF8.GetPreamble()));var text=Encoding.UTF8.GetString(bytes);Assert.Contains("HTT REPORT",text);Assert.Contains(kind,text);Assert.Contains(r.GetProperty("sha256").GetString()!,text);Assert.Equal(n,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));var live=await Live(c,kind);Assert.Equal(Snap(r).GetProperty("rows").GetArrayLength(),live.GetProperty("totalCount").GetInt32());}
 [Fact]public async Task Empty_customer_statement_has_zero_balance_and_real_PDF()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Renée & Sons <Oak>",null,1000));var r=await Statement(c,customer);Assert.Equal(0,D(Snap(r).GetProperty("closing")));var(_,file)=await Generated(c,Id(r),false);var bytes=await c.GetByteArrayAsync($"/api/v1/files/{file}/content");Assert.True(bytes.AsSpan().StartsWith("%PDF-"u8));Assert.True(bytes.Length>10000);}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Statement_AR_matches_source_after_receipt_and_credit(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var sale=await Invoice(c,basis);await Expect(await Send(c,HttpMethod.Post,$"/customers/{sale.Data.Customer}/receipts",new CustomerReceiptInput(55,"BANK_TRANSFER",Code(),[new(sale.Line,55)])),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/sales-invoices/{sale.Invoice}/amount-credit-notes",new AmountCreditInput("Discount",[new(sale.Line,20,2,"Credit")])),HttpStatusCode.Created);var r=await Statement(c,sale.Data.Customer);var s=Snap(r);Assert.Equal("RECONCILED",s.GetProperty("status").GetString());Assert.Equal(33,D(s.GetProperty("closing")));Assert.Equal(110,D(s.GetProperty("debits")));Assert.Equal(77,D(s.GetProperty("credits")));Assert.Equal(0,D(s.GetProperty("difference")));await FinancialReportAssertions.Check(c);var(_,file)=await Generated(c,Id(r),false);Assert.True((await c.GetByteArrayAsync($"/api/v1/files/{file}/content")).Length>10000);}
 [Fact]public async Task Report_and_statement_snapshots_do_not_change_after_later_payments()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var sale=await Invoice(c);var old=await Statement(c,sale.Data.Customer);var report=await Expect(await Capture(c,await Input("ARAP")),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/customers/{sale.Data.Customer}/receipts",new CustomerReceiptInput(55,"BANK_TRANSFER",Code(),[new(sale.Line,55)])),HttpStatusCode.Created);Assert.Equal(old.GetProperty("sha256").GetString(),(await Get(c,$"/customer-statements/{Id(old)}")).GetProperty("sha256").GetString());Assert.True(JsonElement.DeepEquals(Snap(old),Snap(await Get(c,$"/customer-statements/{Id(old)}"))));Assert.True(JsonElement.DeepEquals(Snap(report),Snap(await Get(c,$"/operating-report-runs/{Id(report)}"))));Assert.Equal(55,D(Snap(await Statement(c,sale.Data.Customer)).GetProperty("closing")));await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Opening_balance_uses_prior_postings_and_period_transactions_reconcile()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var sale=await Invoice(c);var day=await Today();var r=await Statement(c,sale.Data.Customer,from:day.AddDays(1),to:day.AddDays(2));var s=Snap(r);Assert.Equal(110,D(s.GetProperty("opening")));Assert.Equal(0,D(s.GetProperty("debits")));Assert.Equal(110,D(s.GetProperty("closing")));Assert.Empty(s.GetProperty("lines").EnumerateArray());}
 [Fact]public async Task Purchasing_events_separate_commitments_receipts_and_bills_and_include_expense_bills()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);var r=await Live(c,"PURCHASING");Assert.Equal(110,D(r.GetProperty("totals").GetProperty("netBilled")));Assert.Equal(0,D(r.GetProperty("totals").GetProperty("orderCommitments")));Assert.Equal("BILL",r.GetProperty("rows")[0].GetProperty("eventType").GetString());await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{b.Supplier}/payments",new SupplierPaymentInput(55,"BANK_TRANSFER",Code(),Allocations:[new(b.Line,55)])),HttpStatusCode.Created);r=await Live(c,"ARAP");Assert.Equal(55,D(r.GetProperty("totals").GetProperty("payables")));Assert.Equal("RECONCILED",r.GetProperty("status").GetString());await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Inventory_report_includes_on_hand_and_in_transit_without_double_counting()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c,10);await StockValuation.InitializeAsync(db.Owner,db.Company,d.Warehouse,d.Product,100,Code(),DatabaseFixture.Issuer,db.Subject);var destination=await Create(c,"/warehouses",new WarehouseMaintenance(Code(),"Destination"));await Expect(await Send(c,HttpMethod.Post,"/inventory/transit-transfers",new TransitDispatchInput(d.Warehouse,destination,Code(),"Dispatched",[new(d.Product,2)])),HttpStatusCode.Created);var r=await Live(c,"INVENTORY");Assert.Equal(80,D(r.GetProperty("totals").GetProperty("onHandValue")));Assert.Equal(20,D(r.GetProperty("totals").GetProperty("inTransitValue")));Assert.Equal("RECONCILED",r.GetProperty("status").GetString());r=await Live(c,"INVENTORY",$"&warehouseId={destination}");Assert.Equal(0,D(r.GetProperty("totals").GetProperty("onHandValue")));Assert.Equal(20,D(r.GetProperty("totals").GetProperty("inTransitValue")));var transfer=(Guid)(await S("SELECT id FROM inventory.transit_transfers WHERE company_id=@c",("c",db.Company)))!;var transferLine=(Guid)(await S("SELECT id FROM inventory.transit_transfer_lines WHERE company_id=@c",("c",db.Company)))!;await Expect(await Send(c,HttpMethod.Post,$"/inventory/transit-transfers/{transfer}/receipts",new TransitEventInput(Code(),"Partial arrival",[new(transferLine,1)])),HttpStatusCode.Created);r=await Live(c,"INVENTORY");Assert.Equal(90,D(r.GetProperty("totals").GetProperty("onHandValue")));Assert.Equal(10,D(r.GetProperty("totals").GetProperty("inTransitValue")));await FinancialReportAssertions.Check(c);}
