 [Theory][InlineData("report")][InlineData("statement")][InlineData("export")]
 public async Task Same_key_replays_and_different_content_conflicts(string operation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input("ARAP");var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Replay",null,100));Guid report=Guid.Empty;if(operation=="export")report=Id(await Expect(await Capture(c,x),HttpStatusCode.Created));var key=Code();Task<HttpResponseMessage> Run(bool changed=false)=>operation switch{"statement"=>Send(c,HttpMethod.Post,$"/customers/{customer}/statements",new StatementPeriodInput(changed?x.From.AddDays(-1):x.From,x.To),key:key),"export"=>Export(c,report,key,changed?2:1),_=>Capture(c,x with{From=changed?x.From.AddDays(-1):x.From},key)};var status=operation=="export"?HttpStatusCode.Accepted:HttpStatusCode.Created;var a=await Expect(await Run(),status);var b=await Expect(await Run(),status);Assert.True(JsonElement.DeepEquals(a,b));await Expect(await Run(true),HttpStatusCode.Conflict);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_export_requests_use_one_worker_job(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var r=await Expect(await Capture(c,await Input("BANKING")),HttpStatusCode.Created);var key=Code();var all=await Task.WhenAll(Export(c,Id(r),key),Export(c,Id(r),sameKey?key:Code()));var a=await Expect(all[0],HttpStatusCode.Accepted);var b=await Expect(all[1],HttpStatusCode.Accepted);Assert.Equal(Id(a),Id(b));var exporter=new Exporter();await using var source=NpgsqlDataSource.Create(db.Worker);await Task.WhenAll(new DocumentWorker(source,new ReportLabPdfRenderer(new()),new Scanner(),new Mailer(),exporter).ProcessOneAsync(),new DocumentWorker(source,new ReportLabPdfRenderer(new()),new Scanner(),new Mailer(),exporter).ProcessOneAsync());Assert.Equal(1,exporter.Calls);Assert.Equal("SUCCEEDED",(await Job(c,Id(a))).GetProperty("state").GetString());}
 [Theory][InlineData("Retry")][InlineData("Permanent")]
 public async Task CSV_failures_leave_no_file_and_can_retry_without_duplicate_financial_effects(string failure)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var r=await Expect(await Capture(c,await Input("BANKING")),HttpStatusCode.Created);var job=Id(await Expect(await Export(c,Id(r)),HttpStatusCode.Accepted));await RunJob(job,new Exporter(new("test_export_failure",failure=="Retry"?WorkFailure.Retry:WorkFailure.Permanent)));var j=await Job(c,job);Assert.Equal(failure=="Retry"?"RETRY":"FAILED",j.GetProperty("state").GetString());Assert.Equal(JsonValueKind.Null,j.GetProperty("outputFileId").ValueKind);if(failure=="Permanent")await Expect(await Send(c,HttpMethod.Post,$"/document-jobs/{job}/retry",new DocumentRetryInput("Renderer restored"),j.GetProperty("version").GetInt64()),HttpStatusCode.Accepted);await RunJob(job);Assert.Equal("SUCCEEDED",(await Job(c,job)).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Statement_mail_uses_PDF_and_unknown_delivery_is_not_blindly_retried()
 {await using var api=new TestApi(db);api.Services.GetRequiredService<DocumentOptions>().MailFrom="reports@htt-test.invalid";using var c=api.Authenticated();var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Mail customer",null,100));var r=await Statement(c,customer);var(pdf,_)=await Generated(c,Id(r),false);var key=Code();Task<HttpResponseMessage> Request()=>Send(c,HttpMethod.Post,$"/documents/{Id(r)}/emails",new DocumentEmailInput(pdf,["customer@htt-test.invalid"],"Account statement","Attached"),1,key);var a=await Expect(await Request(),HttpStatusCode.Accepted);Assert.Equal(Id(a),Id(await Expect(await Request(),HttpStatusCode.Accepted)));await RunJob(Id(a),mailer:new Mailer(new("delivery_unknown",WorkFailure.Unknown)));var view=await Job(c,Id(a));Assert.Equal("UNKNOWN",view.GetProperty("state").GetString());await Expect(await Send(c,HttpMethod.Post,$"/document-jobs/{Id(a)}/retry",new DocumentRetryInput("Do not duplicate"),view.GetProperty("version").GetInt64()),HttpStatusCode.Conflict);await Expect(await Send(c,HttpMethod.Post,$"/documents/{Id(r)}/emails",new DocumentEmailInput(pdf,["customer@htt-test.invalid"],"Account statement","Attached"),1),HttpStatusCode.Conflict);}
 private async Task<(SalesData Data,Guid Order,Guid OrderLine,Guid Receipt,Guid Advance)> Prepay(HttpClient c,string basis)
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Advance service",p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);var q=await Submitted(c,d.Draft(1)with{Lines=[new(d.BoxUnit,Quantity:1,UnitPrice:100)]});var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var ol=(await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0].GetProperty("id").GetGuid();var r=await Expect(await Send(c,HttpMethod.Post,$"/customers/{d.Customer}/receipts",new CustomerReceiptInput(55,"BANK_TRANSFER",Code(),[],[new(ol,55)])),HttpStatusCode.Created);return(d,order,ol,Id(r),Id(r.GetProperty("advances")[0]));}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Customer_advance_history_includes_application_unapplication_refund_and_reversal(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Prepay(c,basis);var s=Snap(await Statement(c,d.Data.Customer));Assert.Equal(55,D(s.GetProperty("advanceBalance")));Assert.Equal(0,D(s.GetProperty("closing")));var version=(await Get(c,$"/sales-orders/{d.Order}/invoiceable")).GetProperty("version").GetInt64();var inv=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{d.Order}/invoices",new InvoiceInput([new(d.OrderLine,1)],"Completed"),version),HttpStatusCode.Created);var line=Id(inv.GetProperty("lines")[0]);var applied=await Expect(await Send(c,HttpMethod.Post,$"/customer-advances/{d.Advance}/apply",new AdvanceApplicationInput(Code(),[new(line,22)])),HttpStatusCode.Created);s=Snap(await Statement(c,d.Data.Customer));Assert.Equal(33,D(s.GetProperty("advanceBalance")));Assert.Equal(88,D(s.GetProperty("closing")));await Expect(await Send(c,HttpMethod.Post,$"/advance-applications/{Id(applied)}/unapply",new SettlementReversalInput(Code(),"Wrong allocation")),HttpStatusCode.Created);var rf=await Expect(await Send(c,HttpMethod.Post,$"/customers/{d.Data.Customer}/refunds",new CustomerRefundInput(11,Code(),"Refund unused advance",AdvanceId:d.Advance)),HttpStatusCode.Created);Assert.Equal(44,D(Snap(await Statement(c,d.Data.Customer)).GetProperty("advanceBalance")));await Expect(await Send(c,HttpMethod.Post,$"/customer-refunds/{Id(rf)}/reverse",new CustomerRefundReversalInput(Code(),"Refund mistake")),HttpStatusCode.Created);var tomorrow=(await Today()).AddDays(1);s=Snap(await Statement(c,d.Data.Customer,from:tomorrow,to:tomorrow.AddDays(1)));Assert.Equal(55,D(s.GetProperty("advanceBalance")));Assert.Equal(110,D(s.GetProperty("opening")));var r=await Live(c,"ARAP");Assert.Equal(55,D(r.GetProperty("totals").GetProperty("customerAdvances")));await FinancialReportAssertions.Check(c);await Expect(await Send(c,HttpMethod.Post,$"/customer-receipts/{d.Receipt}/reverse",new SettlementReversalInput(Code(),"Receipt mistake")),HttpStatusCode.Created);Assert.Equal(0,D(Snap(await Statement(c,d.Data.Customer)).GetProperty("advanceBalance")));await FinancialReportAssertions.Check(c);}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Supplier_advance_history_uses_immutable_events(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c,basis);var r=await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{b.Supplier}/payments",new SupplierPaymentInput(55,"BANK_TRANSFER",Code(),AdvanceAmount:55,Notes:"Next order deposit")),HttpStatusCode.Created);Assert.Equal(55,D((await Live(c,"ARAP")).GetProperty("totals").GetProperty("supplierAdvances")));var payment=Id(r.GetProperty("payment"));var advance=Id(r.GetProperty("advances")[0]);var a=await Expect(await Send(c,HttpMethod.Post,$"/supplier-advances/{advance}/apply",new SupplierAdvanceApplicationInput(Code(),[new(b.Line,22)])),HttpStatusCode.Created);Assert.Equal(33,D((await Live(c,"ARAP")).GetProperty("totals").GetProperty("supplierAdvances")));await Expect(await Send(c,HttpMethod.Post,$"/supplier-advance-applications/{Id(a.GetProperty("application"))}/unapply",new SupplierSettlementReversalInput(Code(),"Wrong allocation")),HttpStatusCode.Created);Assert.Equal(55,D((await Live(c,"ARAP")).GetProperty("totals").GetProperty("supplierAdvances")));var refund=await Expect(await Send(c,HttpMethod.Post,"/supplier-refunds",new SupplierRefundInput(11,Code(),"Unused deposit",AdvanceId:advance)),HttpStatusCode.Created);Assert.Equal(44,D((await Live(c,"ARAP")).GetProperty("totals").GetProperty("supplierAdvances")));await Expect(await Send(c,HttpMethod.Post,$"/supplier-refunds/{Id(refund.GetProperty("refund"))}/reverse",new SupplierRefundReversalInput(Code(),"Wrong refund")),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/supplier-payments/{payment}/reverse",new SupplierSettlementReversalInput(Code(),"Wrong payment")),HttpStatusCode.Created);var final=await Live(c,"ARAP");Assert.Equal(0,D(final.GetProperty("totals").GetProperty("supplierAdvances")));Assert.Equal(0,D(final.GetProperty("advanceControl").GetProperty("supplierDifference")));await FinancialReportAssertions.Check(c);}
