 [Fact]public async Task Scoped_customer_access_is_checked_for_statement_files_and_worker_dispatch()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var one=await Setup(db,c,0);var two=await Create(c,"/customers",new CustomerDraft(Code(),"Other customer",null,100));var staff=await Staff(db,"SALES",one);await S("INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT @c,id,p FROM identity.roles CROSS JOIN unnest(ARRAY['accounting.statements.read','accounting.statements.send','accounting.ledger.read','accounting.reports.read'])p WHERE company_id=@c AND code='SALES'ON CONFLICT DO NOTHING",("c",db.Company));using var salesperson=api.Authenticated(staff.Subject);var allowed=await Statement(salesperson,one.Customer);var denied=await Statement(c,two);await Expect(await Send(salesperson,HttpMethod.Get,$"/customer-statements/{Id(denied)}"),HttpStatusCode.Forbidden);var j=Id(await Expect(await Send(salesperson,HttpMethod.Post,$"/documents/{Id(allowed)}/pdf",version:1),HttpStatusCode.Accepted));await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",staff.Membership));await RunJob(j);Assert.Equal("FAILED",(await Job(c,j)).GetProperty("state").GetString());}
 [Theory][InlineData("report")][InlineData("statement")][InlineData("export")]
 public async Task Late_audit_failure_rolls_back_artifact_job_and_idempotency(string operation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input("BANKING");var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Audit",null,100));var id=operation=="export"?Id(await Expect(await Capture(c,x),HttpStatusCode.Created)):Guid.Empty;var key=Code();var ev=operation switch{"report"=>"reports.operating_captured","statement"=>"accounting.statement_captured",_=>"reports.export_requested"};Task<HttpResponseMessage> Run()=>operation switch{"report"=>Capture(c,x,key),"statement"=>Send(c,HttpMethod.Post,$"/customers/{customer}/statements",new StatementPeriodInput(x.From,x.To),key:key),_=>Export(c,id,key)};await S($"CREATE FUNCTION accounting.test_c03_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='{ev}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c03_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_c03_failure()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM platform.document_jobs WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c03_failure ON platform.audit_events;DROP FUNCTION accounting.test_c03_failure()");}await Expect(await Run(),operation=="export"?HttpStatusCode.Accepted:HttpStatusCode.Created);}
 [Theory][InlineData(true)][InlineData(false)]
 public async Task Concurrent_receipt_and_snapshot_always_use_one_consistent_database_view(bool paymentFirst)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var sale=await Invoice(c);var day=await Today();await using var held=await db.SessionAsync();if(paymentFirst){await Sql.RowsAsync(held,"SELECT accounting.post_receipt(@customer,55,'BANK_TRANSFER','race',@date,@alloc::jsonb,'[]')",default,("customer",sale.Data.Customer),("date",day),("alloc",JsonSerializer.Serialize(new[]{new ReceiptAllocationInput(sale.Line,55)},new JsonSerializerOptions(JsonSerializerDefaults.Web))));var pending=Statement(c,sale.Data.Customer);await Task.Delay(120);Assert.False(pending.IsCompleted);await held.Transaction.CommitAsync();var snapshot=await pending;Assert.Equal(110,D(Snap(snapshot).GetProperty("closing")));Assert.Equal(55,D(Snap(await Statement(c,sale.Data.Customer)).GetProperty("closing")));}else{var rows=await Sql.RowsAsync(held,"SELECT accounting.capture_statement(@customer,@from,@to)AS id",default,("customer",sale.Data.Customer),("from",day),("to",day.AddDays(1)));var payment=Send(c,HttpMethod.Post,$"/customers/{sale.Data.Customer}/receipts",new CustomerReceiptInput(55,"BANK_TRANSFER",Code(),[new(sale.Line,55)]));await Task.Delay(120);Assert.False(payment.IsCompleted);await held.Transaction.CommitAsync();await Expect(await payment,HttpStatusCode.Created);var snapshot=await Get(c,$"/customer-statements/{rows[0]["id"]}");Assert.Equal(110,D(Snap(snapshot).GetProperty("closing")));}await FinancialReportAssertions.Check(c);}
