 public async Task Statement_mail_known_failures_retry_with_the_same_job_identity(string mode)
 {await using var api=new TestApi(db);api.Services.GetRequiredService<DocumentOptions>().MailFrom="reports@htt-test.invalid";using var c=api.Authenticated();var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Mail retry",null,100));var r=await Statement(c,customer);var(pdf,_)=await Generated(c,Id(r),false);var input=new DocumentEmailInput(pdf,["customer@htt-test.invalid"],"Statement","Attached");var j=Id(await Expect(await Send(c,HttpMethod.Post,$"/documents/{Id(r)}/emails",input,1),HttpStatusCode.Accepted));await RunJob(j,mailer:new Mailer(new("provider_unavailable",mode=="Retry"?WorkFailure.Retry:WorkFailure.Permanent)));var view=await Job(c,j);Assert.Equal(mode=="Retry"?"RETRY":"FAILED",view.GetProperty("state").GetString());if(mode=="Permanent")await Expect(await Send(c,HttpMethod.Post,$"/document-jobs/{j}/retry",new DocumentRetryInput("Provider restored"),view.GetProperty("version").GetInt64()),HttpStatusCode.Accepted);await RunJob(j,mailer:new Mailer());view=await Job(c,j);Assert.Equal("SUCCEEDED",view.GetProperty("state").GetString());Assert.Equal("accepted-"+j,view.GetProperty("providerId").GetString());}
