 [Fact]public async Task Unreconciled_AR_control_blocks_statement_capture_without_partial_document()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var sale=await Invoice(c);await using(var s=await db.SessionAsync()){var id=Guid.NewGuid();await Sql.RowsAsync(s,"INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(@id,core.current_company(),'MANUAL_TEST',@n,@date,'CONFIRMED',core.current_actor())",default,("id",id),("n",Code()),("date",await Today()));var party=(Guid)(await S("SELECT party_id FROM crm.customers WHERE company_id=@c AND id=@id",("c",db.Company),("id",sale.Data.Customer)))!;var ar=(Guid)(await S("SELECT id FROM accounting.accounts WHERE company_id=@c AND code='1100'",("c",db.Company)))!;var rev=(Guid)(await S("SELECT id FROM accounting.accounts WHERE company_id=@c AND code='4000'",("c",db.Company)))!;var lines=JsonSerializer.Serialize(new object[]{new{accountId=ar,partyId=party,debit=5},new{accountId=rev,credit=5}});await Sql.RowsAsync(s,"SELECT accounting.post_journal(@id,1,'MANUAL_TEST',@date,'Injected control mismatch',@lines::jsonb)",default,("id",id),("date",await Today()),("lines",lines));await s.Transaction.CommitAsync();}var day=await Today();await Expect(await Send(c,HttpMethod.Post,$"/customers/{sale.Data.Customer}/statements",new StatementPeriodInput(day,day.AddDays(1))),HttpStatusCode.Conflict);Assert.Equal(0L,await S("SELECT count(*)FROM accounting.customer_statements WHERE company_id=@c",("c",db.Company)));}
