 [Fact]public async Task Purchasing_return_cost_is_a_separate_negative_event()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,"NON_CASH",DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Return supplier",null));var po=await Expect(await Send(c,HttpMethod.Post,"/purchase-orders",new PurchaseOrderInput(supplier,d.Warehouse,[new(d.BoxUnit,1,100)])),HttpStatusCode.Created);var oid=Id(po.GetProperty("order"));po=await Expect(await Send(c,HttpMethod.Post,$"/purchase-orders/{oid}/confirm",version:1),HttpStatusCode.OK);var receipt=await Expect(await Send(c,HttpMethod.Post,$"/purchase-orders/{oid}/receipts",new PurchaseReceiptInput(Code(),[new(Id(po.GetProperty("lines")[0]),1)]),2),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/purchase-receipts/{Id(receipt.GetProperty("receipt"))}/returns",new PurchaseReturnInput(Code(),"Unbilled return",[new(Id(receipt.GetProperty("lines")[0]),1)])),HttpStatusCode.Created);var report=await Live(c,"PURCHASING");Assert.Equal(110,D(report.GetProperty("totals").GetProperty("orderCommitments")));Assert.Equal(100,D(report.GetProperty("totals").GetProperty("receiptsCost")));Assert.Equal(-100,D(report.GetProperty("totals").GetProperty("returnedCost")));Assert.Equal(0,D(report.GetProperty("totals").GetProperty("netReceiptsCost")));Assert.Equal(0,D(report.GetProperty("totals").GetProperty("netBilled")));await FinancialReportAssertions.Check(c);}
